components.css:
:root{
  --max-width: 1120px;
  --page-inset: 112px;
  --compact-project-width: 900px;
  --home-max-width: calc((min(clamp(1120px, 75vw, 1600px), calc(100% - var(--page-inset))) + min(var(--compact-project-width), calc(100% - var(--page-inset)))) / 2);
}
.container { max-width: var(--max-width); width: calc(100% - var(--page-inset)); margin-inline: auto; }
#main > .container, .approach-section > .container, .site-footer { max-width: var(--home-max-width); }
.project-showcase-card { display: flex; justify-content: space-evenly; gap: 16px; padding: 12px 16px; overflow: hidden; border: 1px solid var(--line); border-radius: var(--radius); background: var(--paper); }
.project-showcase-card:hover { border-color: var(--control-line); }
.project-tile { display: flex; flex: 0 1 calc(850px / 3); flex-direction: column; align-items: center; justify-content: center; gap: 16px; min-width: 0; padding-block: 4px; text-align: center; }
.project-tile-mark { display: flex; align-items: center; justify-content: center; width: 112px; max-width: 100%; height: 64px; color: var(--ink); }
.project-tile-logo { width: 64px; height: 64px; object-fit: contain; }
.project-tile-logo-onework { width: 112px; max-width: 100%; }
.project-tile-copy { width: 100%; }
.project-tile-description { max-width: 30ch; margin: 8px auto 0; color: var(--muted); font-size: 15px; line-height: 1.8; word-break: keep-all; overflow-wrap: anywhere; text-wrap: pretty; }
.project-tile h3 { font-family: var(--numeric); font-size: 20px; font-weight: 750; line-height: 1.5; letter-spacing: -.025em; }
.project-preview { flex: 0 1 calc(1700px / 3); min-width: 0; align-self: center; }
.project-preview img { display: block; width: 100%; height: auto; object-fit: contain; }

@media (min-width: 1500px) {
  .project-tile-mark { width: 128px; height: 80px; }
  .project-tile-logo { width: 80px; height: 80px; }
  .project-tile-logo-onework { width: 128px; }
  .project-tile h3 { font-size: 22px; }
  .project-tile-description { max-width: 34ch; font-size: 16px; }
}
@media (max-width: 1100px) {
  :root { --page-inset: 80px; }
}
@media (max-width: 820px) {
  :root { --page-inset: 48px; --compact-project-width: 640px; }
  .project-preview-image { height: 300px; }
  .project-showcase-card { display: grid; grid-template-columns: minmax(0, 606px); justify-content: center; padding: 16px; }
  .project-tile { display: grid; grid-template-columns: 80px minmax(0, 1fr); padding: 0; text-align: left; }
  .project-tile-mark { width: 80px; }
  .project-tile-description { max-width: 44ch; margin: 8px 0 0; }
}
@media (max-width: 600px) {
  :root { --page-inset: 40px; }
  .project-showcase-card { border-radius: 12px; }
  .project-tile { grid-template-columns: 60px minmax(0, 1fr); gap: 12px; }
  .project-tile-mark { width: 60px; height: 48px; }
  .project-tile-logo { width: 48px; height: 48px; }
  .project-tile-logo-onework { width: 60px; }
  .project-tile-copy { display: contents; }
  .project-tile h3 { grid-column: 2; grid-row: 1; font-size: 20px; }
  .project-tile-description { grid-column: 1 / -1; margin: 0; max-width: none; }
  .project-preview-image { height: auto; max-height: 320px; }
}
.project-showcase-card{font-family:"Noto Sans KR Variable",sans-serif;color:var(--ink,#262626);text-decoration:none}.project-showcase-card:focus-visible{outline:2px solid var(--ink,#262626);outline-offset:5px}

#main > .container, .approach-section > .container, .site-footer { max-width: var(--home-max-width); }
.approach-section { background: var(--pale); min-height: 600px; padding-block: 80px 88px; }
.approach-section .section-heading { margin-bottom: 32px; }
.approach-grid { display: grid; grid-template-columns: 1fr; }
.approach-grid > article { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: start; gap: 48px; min-width: 0; padding-block: 32px; border-top: 1px solid var(--line); }
.approach-copy { min-width: 0; }
.approach-grid h3 { font-size: 24px; font-weight: 650; letter-spacing: -.025em; line-height: 1.5; word-break: keep-all; }
.approach-copy > p { max-width: 52ch; margin-top: 16px; color: var(--muted); font-size: 18px; line-height: 1.85; word-break: keep-all; overflow-wrap: anywhere; }
.approach-evidence { min-width: 0; width: 100%; }
.approach-test + .approach-test { margin-top: 28px; }
.approach-test > h4 { margin-bottom: 12px; font-size: 16px; font-weight: 600; line-height: 1.6; }
.approach-test-conditions { display: grid; gap: 8px; }
.approach-test-conditions > div { display: grid; grid-template-columns: 88px minmax(0, 1fr); align-items: baseline; gap: 16px; }
.approach-test-conditions dt { color: var(--muted); font-size: 14px; }
.approach-test-conditions dd { font-size: 16px; font-weight: 600; line-height: 1.75; word-break: keep-all; overflow-wrap: anywhere; }
.approach-measure { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }
.approach-measure dt { color: var(--muted); font-size: 14px; line-height: 1.6; }
.approach-measure dd { margin-top: 8px; font-family: var(--numeric); font-size: 36px; font-weight: 650; letter-spacing: -.025em; line-height: 1.25; white-space: nowrap; font-variant-numeric: tabular-nums; }
.approach-measure dd > span { font-size: 14px; font-weight: 500; letter-spacing: 0; }
.approach-evidence .approach-note { margin-top: 16px; color: var(--quiet); font-size: 14px; line-height: 1.75; word-break: keep-all; }
.approach-code { margin: 0; max-width: 100%; white-space: pre-wrap; overflow-wrap: anywhere; font-size: 14px; line-height: 1.9; color: var(--ink); }
.approach-code code { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; }
.approach-link { display: inline-flex; align-items: center; min-height: 44px; margin-top: 20px; padding-block: 8px; font-size: 16px; font-weight: 600; text-decoration: underline; text-decoration-thickness: 1px; }
.approach-link:hover { color: var(--muted); }
@media (max-width: 960px) {
  .approach-section { min-height: 0; padding-block: 72px; }
  .approach-grid > article { grid-template-columns: 1fr; gap: 24px; }
  .approach-evidence { max-width: 480px; }
}
@media (max-width: 600px) {
  .approach-section { padding-block: 64px; }
  .approach-section .section-heading { margin-bottom: 28px; }
  .approach-grid > article { padding-block: 28px; }
  .approach-grid h3 { font-size: 22px; }
  .approach-copy > p { font-size: 16px; }
  .approach-measure dd { font-size: 32px; }
}
@media (max-width: 360px) {
  .approach-measure dd { font-size: 28px; }
  .approach-measure dd > span { display: block; margin-top: 4px; }
}

.process-steps { display: grid; gap: 16px; margin: 0; padding: 0; list-style: none; }
.process-steps > li { display: grid; grid-template-columns: 24px minmax(0, 1fr); align-items: baseline; gap: 12px; min-width: 0; }
.process-step-index { color: var(--process-muted, var(--muted)); font-family: var(--numeric); font-size: 14px; font-weight: 600; line-height: 1.8; font-variant-numeric: tabular-nums; }
.process-step-copy { min-width: 0; }
.process-steps .process-step-copy > strong { display: block; color: inherit; font-size: 16px; font-weight: 650; line-height: 1.6; word-break: keep-all; overflow-wrap: anywhere; }
.process-steps .process-step-copy > p { max-width: 72ch; margin-top: 4px; color: var(--process-muted, var(--muted)); font-size: 14px; line-height: 1.7; word-break: keep-all; overflow-wrap: anywhere; }
